.cu-toaster {
  position: fixed;
  inset-block-end: var(--cu-space-4, var(--cu-space-3));
  inset-inline-end: var(--cu-space-4, var(--cu-space-3));
  z-index: 1100;
  display: grid;
  gap: var(--cu-space-2);
  pointer-events: none;
}

.cu-toaster .cu-toast {
  pointer-events: auto;
}

.cu-toast {
  display: grid;
  gap: var(--cu-space-1);
  min-inline-size: 16rem;
  max-inline-size: min(100%, 24rem);
  padding-block: var(--cu-space-4, var(--cu-space-3));
  padding-inline: var(--cu-space-4, var(--cu-space-3));
  border-radius: var(--cu-radius-md);
  border: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
  border-inline-start-width: 2px;
  border-inline-start-color: var(--cu-color-palette-brand);
  color: var(--cu-color-fg-default);
  background: var(--cu-color-background-elevated, var(--cu-color-background-default));
  box-shadow: var(--cu-shadow-md);
}

.cu-toast--success {
  border-inline-start-color: color-mix(in srgb, var(--cu-color-palette-brand) 80%, green);
}

.cu-toast--warning {
  border-inline-start-color: color-mix(in srgb, var(--cu-color-palette-brand) 80%, orange);
}

.cu-toast--error {
  border-inline-start-color: color-mix(in srgb, var(--cu-color-palette-brand) 80%, red);
}

.cu-toast__title {
  font-weight: var(--cu-typography-weight-semibold, 600);
  letter-spacing: var(--cu-typography-tracking-tight, -0.014em);
}

.cu-toast__description {
  font-size: var(--cu-typography-size-caption, 0.9375rem);
  line-height: var(--cu-typography-line-height-body, 1.5);
  color: var(--cu-color-fg-muted, var(--cu-color-fg-default));
}

.cu-toast__close {
  justify-self: start;
  margin-block-start: var(--cu-space-1);
}

import { ToastPrimitive } from '@chameleon-ui/primitives'
import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  type ComponentProps,
  type ReactNode,
} from 'react'
import './styles.css'

export type ToastStatus = 'info' | 'success' | 'warning' | 'error'
export type ToastPlacement = 'top-start' | 'top-end' | 'bottom-start' | 'bottom-end'

export interface ToastProps {
  open: boolean
  title: string
  description: ReactNode
  status?: ToastStatus
  closeLabel: string
  /** Milliseconds before auto-close. 0 keeps the toast until the parent closes it. */
  duration?: number
  onOpenChange?: (open: boolean) => void
  className?: string
}

export function Toast({
  open,
  title,
  description,
  status = 'info',
  closeLabel,
  duration = 0,
  onOpenChange,
  className,
}: ToastProps) {
  useEffect(() => {
    if (!open || duration <= 0) return
    const timer = window.setTimeout(() => onOpenChange?.(false), duration)
    return () => window.clearTimeout(timer)
  }, [open, duration, onOpenChange])

  if (!open) return null

  const classes = ['cu-toast', `cu-toast--${status}`, className].filter(Boolean).join(' ')

  return (
    <div
      aria-label={title}
      className={classes}
      data-ai-role="toast"
      data-ai-intent="notify-transient"
      data-ai-state={status}
      role="status"
      aria-live={status === 'error' ? 'assertive' : 'polite'}
    >
      <div className="cu-toast__title">{title}</div>
      <div className="cu-toast__description">{description}</div>
      <button className="cu-toast__close" onClick={() => onOpenChange?.(false)} type="button">
        {closeLabel}
      </button>
    </div>
  )
}

export const createToaster = ToastPrimitive.createToaster

export type ToasterStore = ComponentProps<typeof ToastPrimitive.Toaster>['toaster']

export interface ToasterProps {
  toaster: ToasterStore
  closeLabel?: string
  className?: string
}

export function Toaster({ toaster, closeLabel = 'Close', className }: ToasterProps) {
  return (
    <ToastPrimitive.Toaster className={['cu-toaster', className].filter(Boolean).join(' ')} toaster={toaster}>
      {(toast) => {
        const status = normalizeStatus(toast.type)
        return (
          <ToastPrimitive.Root
            className={['cu-toast', `cu-toast--${status}`].join(' ')}
            data-ai-role="toast"
            data-ai-intent="notify-transient"
            data-ai-state={status}
          >
            <ToastPrimitive.Title className="cu-toast__title">{toast.title}</ToastPrimitive.Title>
            {toast.description ? (
              <ToastPrimitive.Description className="cu-toast__description">
                {toast.description}
              </ToastPrimitive.Description>
            ) : null}
            <ToastPrimitive.CloseTrigger aria-label={closeLabel} className="cu-toast__close">
              {closeLabel}
            </ToastPrimitive.CloseTrigger>
          </ToastPrimitive.Root>
        )
      }}
    </ToastPrimitive.Toaster>
  )
}

export interface ToastProviderProps {
  children: ReactNode
  duration?: number
  placement?: ToastPlacement
  closeLabel?: string
}

const ToastStoreContext = createContext<ToasterStore | null>(null)

export function ToastProvider({
  children,
  duration = 4000,
  placement = 'bottom-end',
  closeLabel = 'Close',
}: ToastProviderProps) {
  const toaster = useMemo(
    () => ToastPrimitive.createToaster({ placement, duration, overlap: true }) as ToasterStore,
    [placement, duration],
  )

  return (
    <ToastStoreContext.Provider value={toaster}>
      {children}
      <Toaster closeLabel={closeLabel} toaster={toaster} />
    </ToastStoreContext.Provider>
  )
}

export interface ToastPushInput {
  title: string
  description?: string
  status?: ToastStatus
  duration?: number
}

export function useToast() {
  const toaster = useContext(ToastStoreContext)
  if (!toaster) {
    throw new Error('useToast() requires <ToastProvider> in the tree.')
  }

  return {
    push(input: ToastPushInput) {
      return toaster.create({
        title: input.title,
        description: input.description,
        type: input.status ?? 'info',
        duration: input.duration,
      })
    },
    dismiss(id?: string) {
      const store = toaster as ToasterStore & { remove?: (id?: string) => void }
      store.remove?.(id)
    },
  }
}

function normalizeStatus(value: unknown): ToastStatus {
  if (value === 'success' || value === 'warning' || value === 'error' || value === 'info') {
    return value
  }
  return 'info'
}
